import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { toast } from 'react-toastify';
import {
  UserCircleIcon,
  CreditCardIcon,
  ClockIcon,
  HeartIcon,
  ArrowPathIcon,
  ArrowRightOnRectangleIcon
} from '@heroicons/react/24/outline';
import userService from '../../services/userService';
import orderService from '../../services/orderService';
import OrderItem from '../../components/OrderItem';
import { API_BASE_URL } from '../../config/apiConfig';
import PhoneCard from '../../components/PhoneCard';

const Profile = ({ user }) => {
  const navigate = useNavigate();
  const { register, handleSubmit, formState: { errors }, setValue } = useForm();
  
  const [loading, setLoading] = useState(true);
  const [updateLoading, setUpdateLoading] = useState(false);
  const [data, setData] = useState({ orders: [], history: [], favorites: [] });

  useEffect(() => {
    if (user) {
      setValue('username', user.username);
    }
  }, [user, setValue]);

  useEffect(() => {
    const fetchAllData = async () => {
      if (!user) {
        setLoading(false);
        return;
      }
      try {
        setLoading(true);
        const [orders, history, favorites] = await Promise.all([
          orderService.getMyOrders(),
          userService.getBrowsingHistory(),
          userService.getFavorites()
        ]);
        setData({ orders, history, favorites });
      } catch (error) {
        toast.error('数据加载失败，请稍后重试。');
      } finally {
        setLoading(false);
      }
    };
    fetchAllData();
  }, [user]);

  const updateProfile = async (formData) => {
    setUpdateLoading(true);
    try {
      await userService.updateUserProfile(formData);
      toast.success('个人资料已更新。');
      if (formData.password) {
        setValue('password', '');
      }
      // Note: You might need to refresh user data from parent component
    } catch (error) {
      toast.error('更新失败，请稍后重试。');
    } finally {
      setUpdateLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/');
    window.location.reload(); // Consider a more elegant state management solution
  };

  const Section = ({ title, icon: Icon, children }) => (
    <div className="bg-white rounded-lg shadow">
      <div className="p-6">
        <div className="flex items-center mb-4">
          <Icon className="h-6 w-6 mr-3 text-gray-600" />
          <h2 className="text-xl font-bold text-gray-900">{title}</h2>
        </div>
        <div>{children}</div>
      </div>
    </div>
  );

  const LoadingSpinner = () => (
    <div className="flex justify-center items-center py-10">
      <ArrowPathIcon className="animate-spin h-8 w-8 text-gray-500" />
    </div>
  );

  if (!user) {
    return (
      <div className="text-center py-20">
        <p>请先 <Link to="/login" className="text-blue-600 hover:underline">登录</Link> 以查看个人中心。</p>
      </div>
    );
  }

  return (
    <div className="bg-gray-50 min-h-screen">
      <main className="container mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="flex items-center mb-8">
            <UserCircleIcon className="h-16 w-16 text-gray-400" />
            <div className="ml-4">
              <h1 className="text-3xl font-bold text-gray-900">你好, {user.username}</h1>
              <p className="text-md text-gray-500">欢迎回到你的个人中心</p>
            </div>
        </div>
        
        <div className="space-y-8">
          <Section title="我的订单" icon={CreditCardIcon}>
            {loading ? <LoadingSpinner /> : <OrderList orders={data.orders} />}
          </Section>

          <Section title="个人资料" icon={UserCircleIcon}>
            <ProfileForm user={user} register={register} errors={errors} handleSubmit={handleSubmit(updateProfile)} updateLoading={updateLoading} />
            <div className="mt-6 pt-6 border-t border-gray-200">
               <button
                  onClick={handleLogout}
                  className="w-full flex items-center justify-center px-4 py-2 text-sm font-medium rounded-md text-red-600 bg-red-50 hover:bg-red-100"
                >
                  <ArrowRightOnRectangleIcon className="h-5 w-5 mr-2" />
                  <span>退出登录</span>
                </button>
            </div>
          </Section>

          <Section title="浏览记录" icon={ClockIcon}>
            {loading ? <LoadingSpinner /> : <ProductList products={data.history.map(item => item.phone)} emptyMessage="你还没有浏览任何商品。" link="/" linkText="去逛逛" />}
          </Section>

          <Section title="我的收藏" icon={HeartIcon}>
            {loading ? <LoadingSpinner /> : <ProductList products={data.favorites.map(item => item.phone)} emptyMessage="你的收藏夹是空的。" link="/" linkText="发现更多" />}
          </Section>
        </div>
      </main>
    </div>
  );
};

// --- Sub-components for better organization ---

const ProfileForm = ({ user, register, errors, handleSubmit, updateLoading }) => (
  <form onSubmit={handleSubmit} className="space-y-6">
    <div>
      <label htmlFor="username" className="block text-sm font-medium text-gray-700">
        用户名
      </label>
      <input
        type="text"
        id="username"
        {...register('username', { required: '用户名不能为空' })}
        className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
      />
      {errors.username && <p className="mt-2 text-sm text-red-600">{errors.username.message}</p>}
    </div>
    <div>
      <label htmlFor="password" className="block text-sm font-medium text-gray-700">
        新密码 (可选)
      </label>
      <input
        type="password"
        id="password"
        {...register('password')}
        className="mt-1 block w-full border-gray-300 rounded-md shadow-sm focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
        placeholder="不修改请留空"
      />
    </div>
    <div className="flex justify-end">
      <button
        type="submit"
        disabled={updateLoading}
        className="inline-flex justify-center py-2 px-4 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-gray-400"
      >
        {updateLoading ? (
          <>
            <ArrowPathIcon className="animate-spin h-5 w-5 mr-3" />
            更新中...
          </>
        ) : '保存更改'}
      </button>
    </div>
  </form>
);

const OrderList = ({ orders }) => {
  if (orders.length === 0) {
    return (
      <div className="text-center py-10">
        <CreditCardIcon className="mx-auto h-12 w-12 text-gray-400" />
        <h3 className="mt-2 text-sm font-medium text-gray-900">没有订单</h3>
        <p className="mt-1 text-sm text-gray-500">你还没有创建任何回收订单。</p>
        <div className="mt-6">
          <Link to="/recycle" className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700">
            申请回收
          </Link>
        </div>
      </div>
    );
  }
  return (
    <div className="space-y-4">
      {orders.map((order) => (
        <OrderItem key={order._id} order={order} />
      ))}
    </div>
  );
};

const ProductList = ({ products, emptyMessage, link, linkText }) => {
  if (products.length === 0) {
    return (
      <div className="text-center py-10">
        <HeartIcon className="mx-auto h-12 w-12 text-gray-400" />
        <h3 className="mt-2 text-sm font-medium text-gray-900">{emptyMessage}</h3>
        <div className="mt-6">
          <Link to={link} className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700">
            {linkText}
          </Link>
        </div>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
      {products.map((phone) => (
        phone && <PhoneCard key={phone._id} phone={phone} />
      ))}
    </div>
  );
};

export default Profile;
